*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-page:        #0d0f14;
  --bg-card:        #161922;
  --bg-input:       #1e2230;
  --bg-input-focus: #242840;
  --border:         #2e3348;
  --border-focus:   #5b6af0;
  --border-error:   #e05c5c;
  --text-primary:   #e8eaf6;
  --text-secondary: #8b92b0;
  --text-placeholder: #4d5570;
  --accent:         #5b6af0;
  --accent-hover:   #7080f5;
  --error:          #e05c5c;
  --success-bg:     #0e2b1f;
  --success-border: #2a7a55;
  --success-text:   #4dd49a;
  --radius-sm:      6px;
  --radius-md:      10px;
  --radius-lg:      14px;
  --transition:     0.18s ease;
}

html { font-size: 16px; }

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background-color: var(--bg-page);
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
  line-height: 1.5;
}

/* ── Page wrapper ── */
.page-wrapper {
  width: 100%;
  max-width: 520px;
}

/* ── Card ── */
.form-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
}

/* ── Header ── */
.form-header {
  margin-bottom: 2rem;
}

.form-header h1 {
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  margin-bottom: 0.4rem;
}

.form-header p {
  color: var(--text-secondary);
  font-size: 0.93rem;
}

/* ── Form fields ── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-bottom: 1.4rem;
}

label {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: 0.01em;
}

.required-mark {
  color: var(--accent);
  margin-left: 2px;
}

.optional-mark {
  font-weight: 400;
  color: var(--text-secondary);
  font-size: 0.82rem;
  margin-left: 4px;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 0.95rem;
  padding: 0.65rem 0.85rem;
  width: 100%;
  outline: none;
  transition: border-color var(--transition), background var(--transition), box-shadow var(--transition);
}

input::placeholder {
  color: var(--text-placeholder);
}

input:focus {
  border-color: var(--border-focus);
  background: var(--bg-input-focus);
  box-shadow: 0 0 0 3px rgba(91, 106, 240, 0.18);
}

/* Error state on input */
.form-field.has-error input {
  border-color: var(--border-error);
  box-shadow: 0 0 0 3px rgba(224, 92, 92, 0.15);
}

/* ── Validation message ── */
.validation-message {
  font-size: 0.82rem;
  color: var(--error);
  min-height: 1.1em;
  display: none;
}

.form-field.has-error .validation-message {
  display: block;
}

/* ── Helper text ── */
.helper-text {
  font-size: 0.8rem;
  color: var(--text-secondary);
}

/* ── Submit button ── */
.form-actions {
  margin-top: 0.5rem;
}

button[type="submit"] {
  width: 100%;
  background: var(--accent);
  color: #fff;
  font-size: 0.95rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-sm);
  padding: 0.75rem 1.5rem;
  cursor: pointer;
  letter-spacing: 0.02em;
  transition: background var(--transition), transform 0.1s ease, box-shadow var(--transition);
}

button[type="submit"]:hover {
  background: var(--accent-hover);
  box-shadow: 0 4px 18px rgba(91, 106, 240, 0.35);
}

button[type="submit"]:active {
  transform: scale(0.98);
}

button[type="submit"]:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 3px;
}

button[type="submit"]:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
}

/* ── Success banner ── */
.success-banner {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin-top: 1.2rem;
  padding: 0.8rem 1rem;
  background: var(--success-bg);
  border: 1px solid var(--success-border);
  border-radius: var(--radius-sm);
  color: var(--success-text);
  font-size: 0.9rem;
}

.success-banner[hidden] { display: none; }

/* ── Responsive ── */
@media (max-width: 480px) {
  .form-card { padding: 1.75rem 1.25rem; }
  .form-header h1 { font-size: 1.35rem; }
}
