(() => {
  // ── Field definitions ──────────────────────────────────────────────
  const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
  // Accepts: +1 (555) 000-0000 | 555-000-0000 | (555) 000 0000 | +15550000000 etc.
  const PHONE_RE = /^(\+?1[\s.-]?)?(\(?\d{3}\)?[\s.-]?)?\d{3}[\s.-]?\d{4}$/;

  const fields = {
    fullname: {
      el: document.getElementById('fullname'),
      errorEl: document.getElementById('fullname-error'),
      wrapper: document.getElementById('field-fullname'),
      validate(val) {
        if (!val.trim()) return 'Full name is required.';
        if (val.trim().length < 2) return 'Please enter your full name.';
        return null;
      },
    },
    email: {
      el: document.getElementById('email'),
      errorEl: document.getElementById('email-error'),
      wrapper: document.getElementById('field-email'),
      validate(val) {
        if (!val.trim()) return 'Email address is required.';
        if (!EMAIL_RE.test(val.trim())) return 'Please enter a valid email address (e.g. jane@example.com).';
        return null;
      },
    },
    phone: {
      el: document.getElementById('phone'),
      errorEl: document.getElementById('phone-error'),
      wrapper: document.getElementById('field-phone'),
      validate(val) {
        if (!val.trim()) return null; // optional
        if (!PHONE_RE.test(val.trim())) return 'Please enter a valid phone number, e.g. +1 (555) 000-0000.';
        return null;
      },
    },
  };

  // ── Helpers ────────────────────────────────────────────────────────
  function setError(field, message) {
    field.wrapper.classList.toggle('has-error', !!message);
    field.errorEl.textContent = message || '';
    field.el.setAttribute('aria-invalid', message ? 'true' : 'false');
  }

  function validateField(field) {
    const error = field.validate(field.el.value);
    setError(field, error);
    return !error;
  }

  function validateAll() {
    return Object.values(fields)
      .map(validateField)
      .every(Boolean);
  }

  // ── Inline validation on blur ──────────────────────────────────────
  Object.values(fields).forEach(field => {
    field.el.addEventListener('blur', () => validateField(field));

    // Clear error as user types after a failed submit / blur
    field.el.addEventListener('input', () => {
      if (field.wrapper.classList.contains('has-error')) {
        validateField(field);
      }
    });
  });

  // ── Form submit ────────────────────────────────────────────────────
  const form = document.getElementById('contact-form');
  const submitBtn = document.getElementById('submit-btn');
  const successBanner = document.getElementById('form-success');

  form.addEventListener('submit', e => {
    e.preventDefault();

    if (!validateAll()) {
      // Focus the first invalid field for accessibility
      const firstInvalid = Object.values(fields).find(
        f => f.wrapper.classList.contains('has-error')
      );
      if (firstInvalid) firstInvalid.el.focus();
      return;
    }

    // Simulate async submission
    submitBtn.disabled = true;
    submitBtn.textContent = 'Sending…';

    setTimeout(() => {
      form.reset();
      Object.values(fields).forEach(f => setError(f, null));
      successBanner.hidden = false;
      submitBtn.disabled = false;
      submitBtn.textContent = 'Send Message';
      successBanner.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }, 900);
  });
})();

